//! The station's protocol: the internal model (protocol_types.rs), the AAPI codec between it and the wire
//! (aapi_codec.rs, over protobufjs-style plain objects in proto_object.rs), byte-level edits of frames we pass on
//! (proto_edit.rs), a schema-less view for the journal (raw_proto.rs) and, generated from
//! proto/station-protocol.proto, the wire messages (`pb`).

pub mod aapi_codec;
pub mod ids;
pub mod proto_edit;
pub mod proto_object;
pub mod protocol_types;
pub mod raw_proto;
pub mod structs;

/// The wire messages, generated by prost from proto/station-protocol.proto at build time.
#[allow(clippy::all, missing_docs)]
pub mod pb {
    include!(concat!(env!("OUT_DIR"), "/duowave.station.rs"));
}
